  assistant.sendMessage('Hello from OpenClaw!', { channel: 'discord' });
});

const { renderVideo } = require('@hyperframes/cli');

async function generateComparisonVideo(topicA, topicB) {
  const config = {
    template: 'comparison-template.hf',
    data: { left: topicA, right: topicB },
    voice: { provider: 'azure', language: 'vi-VN', name: 'vi-VN-HoaiNeural' }
  };
  await renderVideo(config, 'output/video.mp4');
  console.log('Video rendered:', 'output/video.mp4');
}

// Example usage
generateComparisonVideo('Thiên thạch', 'Sao băng');

use claw_code::{Agent, Exhibit};

#[tokio::main]
async fn main() {
    // Khởi tạo agent với tên "claw-bot"
    let mut agent = Agent::new("claw-bot");

    // Tải mô tả triển lãm từ cấu hình
    let exhibit = Exhibit::load("museum_hall");

    // Gắn agent vào triển lãm
    agent.attach_exhibit(exhibit).await;

    // Bắt đầu vòng lặp tự trị của agent
    agent.run().await;
}

import android.os.Bundle;
import android.support.v7.app.AppCompatActivity;
import android.view.View;
import com.daimajia.androidanimations.library.Techniques;
import com.daimajia.androidanimations.library.YoYo;

public class MainActivity extends AppCompatActivity {
    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
        View myView = findViewById(R.id.my_view);
        // Áp dụng hiệu ứng Tada lặp 3 lần, mỗi lần 600ms
        YoYo.with(Techniques.Tada)
            .duration(600)
            .repeat(3)
            .playOn(myView);
    }
}

